def init_rand(N,L,sigma): """ Initialize the positions of N particles randomly within a cubic box of side length L, ensuring that no two particles are closer than a distance of sigma. Parameters: ----------- N : int Number of particles to initialize. L : float Length of each side of the cubic box. sigma : float Minimum allowed distance between any two particles. Returns: -------- xyz : ndarray Array of shape (N, 3) containing the initialized positions of the particles. Be sure to use np.random.uniform to initialize it. Raises: ------- Exception If a collision is detected after initialization. """ xyz = np.random.uniform(0,L,(N,3)) for ii in range(N): #print(' Inserting particle %d' % (ii+1)) xyz[ii,:] = np.random.uniform(0,L,3) r1 = xyz[ii,:] collision=1 while(collision): collision=0 for jj in range(ii): r2 = xyz[jj,:] d = dist(r1,r2,L) if d<sigma: collision=1 break if collision: r1 = np.random.uniform(0,L,3) xyz[ii,:] = r1 # verifying all collisions resolved for ii in range(N): r1 = xyz[ii,:] for jj in range(ii): r2 = xyz[jj,:] d = dist(r1,r2,L) if d<sigma: raise Exception('Collision between particles %d and %d' % (ii+1,jj+1)) return xyz
def vMaxBoltz(T, N, m): """ Initialize velocities of particles according to the Maxwell-Boltzmann distribution. Parameters: ----------- T : float Temperature in Kelvin. N : int Number of particles. m : float Molecular mass of the particles in grams per mole (g/mol). Returns: -------- v_xyz : ndarray Array of shape (N, 3) containing the initialized velocities of the particles in nm/ps. """ kB = 1.38064852E-2 # zJ/K kB_J_per_K = kB * 1e-21 m_kg_per_particle = m * 1e-3 / Avogadro # Convert g/mol to kg/particle std_dev_m_per_s = np.sqrt(kB_J_per_K * T / m_kg_per_particle) # Standard deviation for the velocity components in m/s # Initialize velocities from a normal distribution in nm/ps v_xyz = np.random.normal(0, std_dev_m_per_s, (N, 3)) * 1e-3 # Subtract the center of mass velocity in each dimension to remove net momentum v_cm = np.mean(v_xyz, axis=0) v_xyz -= v_cm return v_xyz # v_xyz in nm/ps
def test_main(N, xyz, v_xyz, L, sigma, epsilon, rc, m, dt, tau_T, T_target, tau_P, P_target, nSteps): """ Simulate molecular dynamics using the Velocity-Verlet algorithm and observe properties such as temperature and pressure over a specified number of steps. Parameters: ----------- N : int Number of particles in the system. xyz : ndarray Positions of the particles in the system with shape (N, 3). v_xyz : ndarray Velocities of the particles in the system with shape (N, 3). L : float Length of the cubic box. sigma : float Distance parameter for the Lennard-Jones potential. epsilon : float Depth of the potential well for the Lennard-Jones potential. rc : float Cutoff radius for the potential. m : float Mass of a single particle. dt : float Time step for the simulation. tau_T : float Relaxation time for the temperature coupling. T_target : float Target temperature for the system. tau_P : float Relaxation time for the pressure coupling. P_target : float Target pressure for the system. nSteps : int Number of simulation steps to be performed. Returns: -------- T_traj : ndarray Trajectory of the temperature over the simulation steps. P_traj : ndarray Trajectory of the pressure over the simulation steps. """ T_traj = [] P_traj = [] for step in range(nSteps): xyz, v_xyz, L = velocityVerlet(N, xyz, v_xyz, L, sigma, epsilon, rc, m, dt, tau_T, T_target, tau_P, P_target) if (step+1) % printModulus == 0: T = temperature(v_xyz,m,N) P_kin, P_vir, P = pressure(N,L,T,xyz,sigma,epsilon,rc) T_traj.append(T) P_traj.append(P) T_traj = np.array(T_traj) P_traj = np.array(P_traj) return T_traj, P_traj
# initializing atomic positions and velocities and writing to file
xyz = init_rand(N,L,sigma)
# initializing atomic velocities and writing to file
v_xyz = vMaxBoltz(T_target,N,m)
T_sim, P_sim = test_main(N, xyz, v_xyz, L, sigma, epsilon, rc, m, dt, tau_T, T_target, tau_P, P_target, nSteps)
